<?php require_once __DIR__ . '/../auth/guard.php'; requireRole('teacher'); ?>
<div class="admin-topbar"><div><h1>My Classes &amp; Sections</h1><p>Enroll students in your classes or transfer them between your sections.</p></div></div>
<div id="teacherClassNotice" class="alert d-none" role="status"></div>
<div class="admin-card mb-4"><h2 class="h5 fw-bold">Add / Transfer Student</h2><form id="teacherEnrollForm" class="row g-2">
<div class="col-md-5"><label class="form-label">Student</label><select class="admin-select w-100" id="teacherEnrollStudent" name="student_id" required><option value="">Loading students…</option></select></div>
<div class="col-md-5"><label class="form-label">My class</label><select class="admin-select w-100" id="teacherEnrollClass" name="class_id" required><option value="">Loading classes…</option></select></div>
<div class="col-md-2 d-flex align-items-end"><button class="admin-btn admin-btn-primary w-100" type="submit">Enroll student</button></div>
<div class="col-12"><label><input type="checkbox" id="teacherTransferMode"> Transfer student from previous active class (deactivate old enrollment)</label></div>
</form></div>
<div class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Class / Section</th><th>Grade</th><th>School year</th><th>Active students</th><th>Status</th></tr></thead><tbody id="teacherClassRows"><tr><td colspan="5">Loading classes…</td></tr></tbody></table></div></div>
<script>
(function(){const ep='api/system_management.php',form=document.getElementById('teacherEnrollForm'),rows=document.getElementById('teacherClassRows'),student=document.getElementById('teacherEnrollStudent'),cls=document.getElementById('teacherEnrollClass'),notice=document.getElementById('teacherClassNotice');if(!form||form.dataset.bound)return;form.dataset.bound='1';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function msg(t,ok){notice.className='alert '+(ok?'alert-success':'alert-danger');notice.textContent=t}
async function load(){try{const r=await fetch(ep+'?view=classes',{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);student.innerHTML='<option value="">Select student</option>'+(d.students||[]).map(s=>'<option value="'+s.student_id+'">'+esc(s.full_name+(s.student_number?' · '+s.student_number:''))+'</option>').join('');cls.innerHTML='<option value="">Select your class</option>'+(d.classes||[]).filter(c=>c.status==='active').map(c=>'<option value="'+c.class_id+'">'+esc(c.class_name+(c.section?' - '+c.section:'')+' ('+c.school_year+')')+'</option>').join('');rows.innerHTML=d.classes.length?d.classes.map(c=>'<tr><td><strong>'+esc(c.class_name+(c.section?' - '+c.section:''))+'</strong></td><td>'+esc(c.grade_level||'—')+'</td><td>'+esc(c.school_year)+'</td><td>'+Number(c.student_count)+'</td><td>'+esc(c.status)+'</td></tr>').join(''):'<tr><td colspan="5" class="text-center text-muted">No classes are assigned to your account. Ask an administrator to assign a class.</td></tr>'}catch(e){msg(e.message,false);rows.innerHTML='<tr><td colspan="5">'+esc(e.message)+'</td></tr>'}}
form.addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(form));body.action=document.getElementById('teacherTransferMode').checked?'class_transfer':'class_enroll';try{const r=await fetch(ep,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);msg(d.message,true);form.reset();await load()}catch(e){msg(e.message,false)}});load()})();
</script>